const ins = $input.all().map(i => i.json).filter(r => r.inscripcion_id);
const evento = $('Buscar evento').first().json;
const body = $('Webhook').first().json.body;
const usuario_id = $('Buscar usuario').first().json.usuario_id;

const confirmadas = ins.filter(r => r.estado === 'CONFIRMADA').length;
const espera = ins.filter(r => r.estado === 'LISTA_ESPERA').length;
const duplicado = ins.some(r => r.usuario_id === usuario_id && ['CONFIRMADA', 'LISTA_ESPERA'].includes(r.estado));
const cupos = Number(evento.capacidad) - confirmadas;

return [{ json: {
  usuario_id,
  evento_id: evento.evento_id,
  nombre_acreditacion: body.nombre_acreditacion,
  observaciones: body.observaciones || '',
  cupos_disponibles: cupos,
  duplicado,
  estado_nuevo: cupos > 0 ? 'CONFIRMADA' : 'LISTA_ESPERA',
  orden_espera: cupos > 0 ? '' : espera + 1
}}];

const lista = $input.all()
  .map(i => i.json)
  .filter(r => r.inscripcion_id)
  .map(r => ({
    inscripcion_id: r.inscripcion_id,
    evento_id: r.evento_id,
    estado: r.estado,
    fecha_inscripcion: r.fecha_inscripcion,
    nombre_acreditacion: r.nombre_acreditacion,
    observaciones: r.observaciones,
    orden_espera: r.orden_espera
  }));

return [{ json: { ok: true, total: lista.length, inscripciones: lista } }];;
